		public int GetIncreaseMaxCorruptionPercentagePerArea(MapHandler mapHandler)
		{
			if (mapHandler.CurrentAreaIndex == 0)
			{
				if (mapHandler.BossBattle)
				{
					return increaseMaxCorruptionPercentageHighReefBosses;
				}
				return increaseMaxCorruptionPercentageHighReef;
			}
			if (mapHandler.CurrentAreaIndex == 1)
			{
				if (mapHandler.BossBattle)
				{
					return increaseMaxCorruptionPercentageAstropolisRuinBosses;
				}
				return increaseMaxCorruptionPercentageAstropolisRuins;
			}
			if (mapHandler.BossBattle)
			{
				return increaseMaxCorruptionPercentageGroundZeroBosses;
			}
			return increaseMaxCorruptionPercentageGroundZero;
		}
