	public float GetDifficultyLevelIncreaseMaxCorruptionPercentage()
	{
		int num = 0;
		for (int i = 0; i < difficultyLevelDatas.Length && !IsIndexHigherThanDifficultyLevel(i); i++)
		{
			DifficultyLevelData difficultyLevelData = difficultyLevelDatas[i];
			if (difficultyLevelData.IsIncreaseMaxCorruptionPercentage)
			{
				num = ((!difficultyLevelData.IncreaseMaxCorruptionPercentageCustomPerArea) ? (num + difficultyLevelData.IncreaseMaxCorruptionPercentage) : (num + difficultyLevelData.GetIncreaseMaxCorruptionPercentagePerArea(mapHandler)));
			}
		}
		return (float)num / 100f;
	}

	public List<StartingEffect> GetDifficultyLevelStartingEffects(CorruptedAnimalData corruptedAnimalData, bool startOfBattle)
	{
		List<StartingEffect> list = new List<StartingEffect>();
		for (int i = 0; i < difficultyLevelDatas.Length && !IsIndexHigherThanDifficultyLevel(i); i++)
		{
			DifficultyLevelData difficultyLevelData = difficultyLevelDatas[i];
			if (difficultyLevelData.IsStartingEffect && (startOfBattle || !difficultyLevelData.StartOfBattle))
			{
				int num = 0;
				list.Add(new StartingEffect(effectAmount: (!difficultyLevelData.VariableAmount) ? difficultyLevelData.EffectAmount : ((mapHandler.CurrentNodeData.NodeEnum != 0 && mapHandler.CurrentNodeData.NodeEnum != NodeEnum.EVENT) ? ((mapHandler.CurrentNodeData.NodeEnum == NodeEnum.BATTLEHARD) ? difficultyLevelData.HardEnemyEffectAmount : (corruptedAnimalData.CorruptionSource ? difficultyLevelData.BossEffectAmount : ((!corruptedAnimalData.Minion) ? difficultyLevelData.MinionEffectAmount : difficultyLevelData.MinionEffectAmount))) : difficultyLevelData.NormalEnemyEffectAmount), effect: difficultyLevelData.Effect));
			}
		}
		return list;
	}

