	public void InitializeAstreasHeartLevelAreaOrder(AreaEnum[] areaOrder)
	{
		areaOrder[^1] = GetAstreasHeartAreaEnum();
	}

	private AreaEnum GetAstreasHeartAreaEnum()
	{
		for (int num = difficultyLevelDatas.Length - 1; num >= 0; num--)
		{
			if (!IsIndexHigherThanDifficultyLevel(num))
			{
				if (difficultyLevelDatas[num].IsFightSixCorruptedOracles)
				{
					difficultyLevelDatas[num].OnSetupMapFightMoreThanOneCorruptedOracleEvent.Raise();
					return difficultyLevelDatas[num].FightMoreThanOneCorruptedOracleAreaEnum;
				}
				if (difficultyLevelDatas[num].IsFightTwoCorruptedOracles)
				{
					difficultyLevelDatas[num].OnSetupMapFightMoreThanOneCorruptedOracleEvent.Raise();
					return difficultyLevelDatas[num].FightMoreThanOneCorruptedOracleAreaEnum;
				}
			}
		}
		return normalArea4AreaEnum;
	}

