	private bool IsIndexHigherThanDifficultyLevel(int i)
	{
		return i > GetCurrentDifficultyLevelIndex();
	}

	public int GetCurrentDifficultyLevelIndex()
	{
		int num = -1;
		if (!GameScenesUtils.IsBattleScene())
		{
			return anomalyLevel ? ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterCurrentAnomalyLevel : ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterCurrentAstreaLevel;
		}
		return anomalyLevel ? ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAnomalyLevel : ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAstreaLevel;
	}

	private bool IsCurrentDifficultyLevel(int i)
	{
		return i == GetCurrentDifficultyLevelIndex();
	}

	public void InitializeDifficultyLevelEveryXTurnsEffect()
	{
		if (mapHandler.IsOnAstreasHeart)
		{
			return;
		}
		for (int i = 0; i < difficultyLevelDatas.Length && !IsIndexHigherThanDifficultyLevel(i); i++)
		{
			DifficultyLevelData difficultyLevelData = difficultyLevelDatas[i];
			if (difficultyLevelData.IsEveryXTurnsEffect)
			{
				difficultyLevelData.EveryXTurnsOmenData.Initialize(null);
			}
		}
	}

	public List<Effect> GetDifficultyLevelEveryXTurnsEffects()
	{
		List<Effect> list = new List<Effect>();
		for (int i = 0; i < difficultyLevelDatas.Length && !IsIndexHigherThanDifficultyLevel(i); i++)
		{
			DifficultyLevelData difficultyLevelData = difficultyLevelDatas[i];
			if (difficultyLevelData.IsEveryXTurnsEffect && !difficultyLevelDatas[i].UseTagForDescription)
			{
				BattleAction battleAction = difficultyLevelData.EveryXTurnsOmenData.BattleAction;
				if (battleAction is DefaultEffectAction)
				{
					DefaultEffectAction defaultEffectAction = battleAction as DefaultEffectAction;
					list.Add(defaultEffectAction.Effect);
				}
			}
		}
		return list;
	}

	public Effect GetCurrentDifficultyLevelEveryXTurnsEffect()
	{
		for (int i = 0; i < difficultyLevelDatas.Length; i++)
		{
			if (!IsCurrentDifficultyLevel(i))
			{
				continue;
			}
			DifficultyLevelData difficultyLevelData = difficultyLevelDatas[i];
			if (difficultyLevelData.IsEveryXTurnsEffect)
			{
				BattleAction battleAction = difficultyLevelData.EveryXTurnsOmenData.BattleAction;
				if (battleAction is DefaultEffectAction)
				{
					return (battleAction as DefaultEffectAction).Effect;
				}
			}
		}
		return null;
	}

	public void UnsubscribeDifficultyLevelEveryXTurnsEffect()
	{
		for (int i = 0; i < difficultyLevelDatas.Length && !IsIndexHigherThanDifficultyLevel(i); i++)
		{
			DifficultyLevelData difficultyLevelData = difficultyLevelDatas[i];
			if (difficultyLevelData.IsEveryXTurnsEffect)
			{
				difficultyLevelData.EveryXTurnsOmenData.OmenRemoved();
			}
		}
	}

	public List<StartingEffect> GetDifficultyLevelPlayerStartingEffects()
	{
		List<StartingEffect> list = new List<StartingEffect>();
		if (mapHandler.IsOnAstreasHeart)
		{
			return list;
		}
		for (int i = 0; i < difficultyLevelDatas.Length && !IsIndexHigherThanDifficultyLevel(i); i++)
		{
			DifficultyLevelData difficultyLevelData = difficultyLevelDatas[i];
			if (difficultyLevelData.IsEveryXActions)
			{
				int everyXActionsTrigger = difficultyLevelData.EveryXActionsTrigger;
				list.Add(new StartingEffect(difficultyLevelData.EveryXActionsCorruptActionEffect, everyXActionsTrigger));
			}
		}
		return list;
	}

	public List<OmenLogicActionFace> GetDifficultyLevelPlayerStartingAction()
	{
		List<OmenLogicActionFace> list = new List<OmenLogicActionFace>();
		if (mapHandler.IsOnAstreasHeart)
		{
			return list;
		}
		for (int i = 0; i < difficultyLevelDatas.Length && !IsIndexHigherThanDifficultyLevel(i); i++)
		{
			DifficultyLevelData difficultyLevelData = difficultyLevelDatas[i];
			if (difficultyLevelData.IsStartingAction)
			{
				list.Add(difficultyLevelData.OmenLogicActionFaces.GetItemCheckingArrayLength(mapHandler.CurrentAreaIndex));
			}
		}
		return list;
	}

	public List<OmenLogicActionFace> GetDifficultyLevelOnShuffleDicePoolAction()
	{
		List<OmenLogicActionFace> list = new List<OmenLogicActionFace>();
		for (int i = 0; i < difficultyLevelDatas.Length && !IsIndexHigherThanDifficultyLevel(i); i++)
		{
			DifficultyLevelData difficultyLevelData = difficultyLevelDatas[i];
			if (difficultyLevelData.IsOnShuffleDicePoolAction || difficultyLevelData.IsSecondOnShuffleDicePoolAction)
			{
				list.Add(difficultyLevelData.OmenLogicActionFaces.GetItemCheckingArrayLength(mapHandler.CurrentAreaIndex));
			}
		}
		return list;
	}

	public Tag GetCurrentDifficultyTag()
	{
		for (int i = 0; i < difficultyLevelDatas.Length; i++)
		{
			if (IsCurrentDifficultyLevel(i))
			{
				DifficultyLevelData difficultyLevelData = difficultyLevelDatas[i];
				if (difficultyLevelData.UseTagForDescription)
				{
					return difficultyLevelData.Tag;
				}
			}
		}
		return null;
	}

	public string GetLocalizedDifficultyLevelDescription(int index)
	{
		DifficultyLevelData difficultyLevelData = difficultyLevelDatas[index];
		string difficultyLevelDescriptionID = difficultyLevelData.DifficultyLevelDescriptionID;
		if (difficultyLevelData.IsStartingEffect)
		{
			if (difficultyLevelData.StartOfBattle)
			{
				return onStartOfBattleOmenData.GetStartOfBattleLocalizedDescription() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + difficultyLevelData.StartOfBattleBattleActionForDescription.GetActionDescription(difficultyLevelData.EffectAmount).LowercaseFirst();
			}
			return Smart.Format(GetLocalizedString(difficultyLevelDescriptionID), difficultyLevelData.Effect.GetEffectName());
		}
		if (difficultyLevelData.IsStartingAction || difficultyLevelData.IsOnShuffleDicePoolAction)
		{
			ActionFace actionFace = difficultyLevelData.OmenLogicActionFaces.First().ActionFace;
			int amount = (difficultyLevelData.UseDifferentValueForDescription ? difficultyLevelData.DifferentValueForDescription : actionFace.ActionValue);
			if (difficultyLevelData.IsStartingAction)
			{
				return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedStartOfBattle() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + actionFace.BattleAction.GetActionDescription(amount).LowercaseFirst();
			}
			if (difficultyLevelData.IsOnShuffleDicePoolAction)
			{
				return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetWheneverYouShuffleYourDicePool(), actionFace.BattleAction.GetActionDescription(amount).LowercaseFirst());
			}
		}
		else
		{
			if (difficultyLevelData.IsTargetsReceivesCorruption)
			{
				return Smart.Format(GetLocalizedString(difficultyLevelDescriptionID), turnsToStartActivatingReceiveCorruptionAmount, targetsReceiveCorruptionAmount);
			}
			if (difficultyLevelData.IsEveryXTurnsEffect)
			{
				return difficultyLevelData.EveryXTurnsOmenData.OmenConvertedDescription();
			}
			if (difficultyLevelData.IsEveryXActions)
			{
				string localizedString = GetLocalizedString("AnomalyLevelXEveryXActionsBase");
				int corruptAmount = difficultyLevelData.EveryXActionsCorruptActionEffect.CorruptAmount;
				BattleAction corruptAction = difficultyLevelData.EveryXActionsCorruptActionEffect.CorruptAction;
				return Smart.Format(localizedString, corruptAction.GetActionDescription(corruptAmount).UppercaseFirst().RemoveLast(), difficultyLevelData.EveryXActionsTrigger) + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("ReceiveCorruptionAnomalyLevelNonModified");
			}
		}
		string text = "";
		if (difficultyLevelData.IsSecondOnShuffleDicePoolAction)
		{
			ActionFace actionFace2 = difficultyLevelData.OmenLogicActionFaces.First().ActionFace;
			int amount2 = (difficultyLevelData.UseDifferentValueForDescription ? difficultyLevelData.DifferentValueForDescription : actionFace2.ActionValue);
			text = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetWheneverYouShuffleYourDicePool(), actionFace2.BattleAction.GetActionDescription(amount2).LowercaseFirst());
		}
		return GetLocalizedString(difficultyLevelDescriptionID) + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + text;
	}

	private string GetLocalizedString(string id)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(id);
	}

	public string GetUnlockedAmountLocalized(int additionalUnlockedAmount = 0)
	{
		CharacterProgression currentCharacterProgression = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression;
		int num = -1;
		int num2 = -1;
		if (anomalyLevel)
		{
			num = currentCharacterProgression.UnlockedAnomalyLevel + additionalUnlockedAmount;
			num2 = ((num != difficultyLevelDatas.Length - 1) ? (difficultyLevelDatas.Length - 2) : (difficultyLevelDatas.Length - 1));
		}
		else
		{
			num = currentCharacterProgression.UnlockedAstreaLevel + additionalUnlockedAmount;
			num2 = ((num != difficultyLevelDatas.Length - 1) ? (difficultyLevelDatas.Length - 2) : (difficultyLevelDatas.Length - 1));
		}
		return Smart.Format(GetLocalizedString("UnlockedAmount"), num, num2);
	}

	public string GetUnlockedAmountLocalizedUnlockable()
	{
		CharacterProgression currentCharacterProgression = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression;
		if (anomalyLevel)
		{
			if (currentCharacterProgression.UnlockedAnomalyLevel == -1)
			{
				return GetUnlockedAmountLocalized(2);
			}
			return GetUnlockedAmountLocalized(1);
		}
		if (currentCharacterProgression.UnlockedAstreaLevel == -1)
		{
			return GetUnlockedAmountLocalized(2);
		}
		return GetUnlockedAmountLocalized(1);
	}
